    кисть.fillStyle = цвет(дымка.крышаС);
    кисть.beginPath();
    кисть.moveTo(xa, ta); кисть.lineTo(xb, tb);
    кисть.lineTo(xb, tb + шb * ст.кромка); кисть.lineTo(xa, ta + ша * ст.кромка);
