  const доля = с.далеко / НАСТРОЙКИ.карта.видимость;
  if (доля > 1) return;
  const y = строкаПоДоле(доля), ш = ширинаДомаНаДоле(доля);
  const высота = ш * ст.высота;
  const дымка = вДымке(п, доля, плотность);
  const ц = серединаДороги(y, изгиб);
  const пш = ширинаДороги(y) * ст.проёмШире / 2;
  const пв = высота * ст.проёмВысота;
  const кладка = new Path2D();
  кладка.rect(0, y - высота, х.ширина, высота);
  кладка.moveTo(ц - пш, y);
  кладка.lineTo(ц - пш, y - пв + пш);
